# Calculating Stop Loss as 1% of Account Balance in MQL5

There are different approaches depending on whether you want to risk 1% of your balance OR set the stop loss distance based on 1% risk.

## Approach 1: Calculate Stop Loss Distance Based on 1% Risk

This calculates how many points/pips your stop loss should be to risk exactly 1% of your balance:

```mql5
//+------------------------------------------------------------------+
//| Calculate Stop Loss distance for 1% risk                         |
//+------------------------------------------------------------------+
double CalculateSLDistance(string symbol, double lotSize, double riskPercent = 1.0)
{
    double accountBalance = AccountInfoDouble(ACCOUNT_BALANCE);
    double riskAmount = accountBalance * (riskPercent / 100.0);  // 1% of balance

    // Get tick value and tick size
    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);

    // Calculate SL distance in price
    double slDistance = (riskAmount * tickSize) / (lotSize * tickValue);

    return slDistance;
}

//+------------------------------------------------------------------+
//| Example: Open BUY order with 1% risk stop loss                   |
//+------------------------------------------------------------------+
void OpenBuyWith1PercentRisk()
{
    string symbol = _Symbol;
    double lotSize = 0.1;  // Your lot size

    double ask = SymbolInfoDouble(symbol, SYMBOL_ASK);
    double slDistance = CalculateSLDistance(symbol, lotSize, 1.0);
    double stopLoss = ask - slDistance;

    // Normalize the stop loss price
    int digits = (int)SymbolInfoInteger(symbol, SYMBOL_DIGITS);
    stopLoss = NormalizeDouble(stopLoss, digits);

    // Open the trade
    MqlTradeRequest request = {};
    MqlTradeResult result = {};

    request.action = TRADE_ACTION_DEAL;
    request.symbol = symbol;
    request.volume = lotSize;
    request.type = ORDER_TYPE_BUY;
    request.price = ask;
    request.sl = stopLoss;
    request.deviation = 10;
    request.magic = 123456;

    OrderSend(request, result);
}
```

## Approach 2: Calculate Lot Size for Fixed SL Distance with 1% Risk

If you have a fixed stop loss distance and want to calculate the lot size:

```mql5
//+------------------------------------------------------------------+
//| Calculate lot size for 1% risk with fixed SL distance            |
//+------------------------------------------------------------------+
double CalculateLotSize(string symbol, double slDistancePoints, double riskPercent = 1.0)
{
    double accountBalance = AccountInfoDouble(ACCOUNT_BALANCE);
    double riskAmount = accountBalance * (riskPercent / 100.0);

    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);

    // Calculate lot size
    double lotSize = (riskAmount * tickSize) / (slDistancePoints * tickValue);

    // Normalize lot size to broker requirements
    double minLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
    double maxLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
    double lotStep = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);

    // Round to lot step
    lotSize = MathFloor(lotSize / lotStep) * lotStep;

    // Clamp to min/max
    lotSize = MathMax(minLot, MathMin(maxLot, lotSize));

    return lotSize;
}
```

## Complete Example with Both Approaches

```mql5
//+------------------------------------------------------------------+
//| Complete trading function with 1% risk management                |
//+------------------------------------------------------------------+
void TradeWith1PercentRisk(ENUM_ORDER_TYPE orderType, double slPoints = 0, double tpPoints = 0)
{
    string symbol = _Symbol;
    double riskPercent = 1.0;  // 1% risk

    double accountBalance = AccountInfoDouble(ACCOUNT_BALANCE);
    double riskAmount = accountBalance * (riskPercent / 100.0);

    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);
    double point = SymbolInfoDouble(symbol, SYMBOL_POINT);
    int digits = (int)SymbolInfoInteger(symbol, SYMBOL_DIGITS);

    double price, sl, tp;

    if(orderType == ORDER_TYPE_BUY)
    {
        price = SymbolInfoDouble(symbol, SYMBOL_ASK);

        // If SL points specified, calculate lot size
        // Otherwise use fixed lot and calculate SL distance
        if(slPoints > 0)
        {
            sl = price - slPoints * point;
        }
        else
        {
            slPoints = 500;  // Default 500 points if not specified
            sl = price - slPoints * point;
        }

        tp = (tpPoints > 0) ? price + tpPoints * point : 0;
    }
    else // SELL
    {
        price = SymbolInfoDouble(symbol, SYMBOL_BID);

        if(slPoints > 0)
        {
            sl = price + slPoints * point;
        }
        else
        {
            slPoints = 500;
            sl = price + slPoints * point;
        }

        tp = (tpPoints > 0) ? price - tpPoints * point : 0;
    }

    // Calculate lot size for 1% risk
    double slDistance = slPoints * point;
    double lotSize = (riskAmount * tickSize) / (slDistance * tickValue);

    // Normalize lot size
    double minLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
    double maxLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
    double lotStep = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);

    lotSize = MathFloor(lotSize / lotStep) * lotStep;
    lotSize = MathMax(minLot, MathMin(maxLot, lotSize));

    // Normalize prices
    sl = NormalizeDouble(sl, digits);
    tp = NormalizeDouble(tp, digits);

    // Send order
    MqlTradeRequest request = {};
    MqlTradeResult result = {};

    request.action = TRADE_ACTION_DEAL;
    request.symbol = symbol;
    request.volume = lotSize;
    request.type = orderType;
    request.price = price;
    request.sl = sl;
    request.tp = tp;
    request.deviation = 10;
    request.magic = 123456;
    request.comment = "1% Risk Trade";

    if(OrderSend(request, result))
    {
        Print("Order sent: Risk=", riskAmount, " Lots=", lotSize, " SL=", sl);
    }
    else
    {
        Print("Order failed: ", result.retcode);
    }
}
```

## Key Points

| Function | Purpose |
|----------|---------|
| `AccountInfoDouble(ACCOUNT_BALANCE)` | Gets current account balance |
| `SYMBOL_TRADE_TICK_VALUE` | Value of 1 tick movement per lot |
| `SYMBOL_TRADE_TICK_SIZE` | Size of 1 tick in price |
| `SYMBOL_VOLUME_STEP` | Minimum lot increment |

**Note:** For accounts with different currencies than the trading symbol, the tick value automatically accounts for currency conversion.

